import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            sc.nextInt();
        }
        int pos = sc.nextInt();
        System.out.println(pos > 0 ? "Cycle" : "No Cycle");
        sc.close();
    }
}
